  141: /// Only _static_ data send in this packet !!!
  142: void QueryHandlers::HandleGameObjectQuery(WorldSession& session, WorldPacket& recv_data)
  143: {
  144:     uint32 entryID;
  145:     recv_data >> entryID;
  146:     ObjectGuid guid;
  147:     recv_data >> guid;
  148: 
  149:     const GameObjectInfo* info = ObjectMgr::GetGameObjectInfo(entryID);
  150:     if (info)
  151:     {
  152:         std::string Name;
  153:         std::string IconName;
  154:         std::string CastBarCaption;
  155: 
  156:         Name = info->name;
  157:         IconName = info->IconName;
  158:         CastBarCaption = info->castBarCaption;
  159: 
  160:         int loc_idx = session.GetSessionDbLocaleIndex();
  161:         if (loc_idx >= 0)
  162:         {
  163:             GameObjectLocale const* gl = sObjectMgr.GetGameObjectLocale(entryID);
  164:             if (gl)
  165:             {
  166:                 if (gl->Name.size() > size_t(loc_idx) && !gl->Name[loc_idx].empty())
  167:                 {
  168:                     Name = gl->Name[loc_idx];
  169:                 }
  170:                 if (gl->CastBarCaption.size() > size_t(loc_idx) && !gl->CastBarCaption[loc_idx].empty())
  171:                 {
  172:                     CastBarCaption = gl->CastBarCaption[loc_idx];
  173:                 }
  174:             }
  175:         }
  176:         DETAIL_LOG("WORLD: CMSG_GAMEOBJECT_QUERY '%s' - Entry: %u. ", info->name, entryID);
  177:         WorldPacket data(SMSG_GAMEOBJECT_QUERY_RESPONSE, 150);
  178:         data << uint32(entryID);
  179:         data << uint32(info->type);
  180:         data << uint32(info->displayId);
  181:         data << Name;
  182:         data << uint8(0) << uint8(0) << uint8(0);           // name2, name3, name4
  183:         data << IconName;                                   // 2.0.3, string. Icon name to use instead of default icon for go's (ex: "Attack" makes sword)
  184:         data << CastBarCaption;                             // 2.0.3, string. Text will appear in Cast Bar when using GO (ex: "Collecting")
  185:         data << info->unk1;                                 // 2.0.3, string
  186:         data.append(info->raw.data, 24);
  187:         data << float(info->size);                          // go size
  188:         for (uint32 i = 0; i < 6; ++i)
  189:         {
  190:             data << uint32(info->questItems[i]);            // itemId[6], quest drop
  191:         }
  192:         session.SendPacket(&data);
  193:         DEBUG_LOG("WORLD: Sent SMSG_GAMEOBJECT_QUERY_RESPONSE");
  194:     }
  195:     else
  196:     {
  197:         DEBUG_LOG("WORLD: CMSG_GAMEOBJECT_QUERY - Guid: %s Entry: %u Missing gameobject info!",
  198:                   guid.GetString().c_str(), entryID);
  199:         WorldPacket data(SMSG_GAMEOBJECT_QUERY_RESPONSE, 4);
  200:         data << uint32(entryID | 0x80000000);
  201:         session.SendPacket(&data);
  202:         DEBUG_LOG("WORLD: Sent SMSG_GAMEOBJECT_QUERY_RESPONSE");
  203:     }
  204: }
