  264:  * @brief Handles an NPC text query and sends localized gossip text options.
  265:  *
  266:  * @param recv_data The incoming NPC text query packet.
  267:  */
  268: void QueryHandlers::HandleNpcTextQuery(WorldSession& session, WorldPacket& recv_data)
  269: {
  270:     uint32 textID;
  271:     ObjectGuid guid;
  272: 
  273:     recv_data >> textID;
  274:     recv_data >> guid;
  275: 
  276:     DETAIL_LOG("WORLD: CMSG_NPC_TEXT_QUERY ID '%u'", textID);
  277: 
  278:     session.GetPlayer()->SetTargetGuid(guid);
  279: 
  280:     GossipText const* pGossip = sObjectMgr.GetGossipText(textID);
  281: 
  282:     WorldPacket data(SMSG_NPC_TEXT_UPDATE, 100);            // guess size
  283:     data << textID;
  284: 
  285:     if (!pGossip)
  286:     {
  287:         for (uint32 i = 0; i < MAX_GOSSIP_TEXT_OPTIONS; ++i)
  288:         {
  289:             data << float(0);
  290:             data << "Greetings $N";
  291:             data << "Greetings $N";
  292:             data << uint32(0);
  293:             data << uint32(0);
  294:             data << uint32(0);
  295:             data << uint32(0);
  296:             data << uint32(0);
  297:             data << uint32(0);
  298:             data << uint32(0);
  299:         }
  300:     }
  301:     else
  302:     {
  303:         std::string Text_0[MAX_GOSSIP_TEXT_OPTIONS], Text_1[MAX_GOSSIP_TEXT_OPTIONS];
  304:         for (int i = 0; i < MAX_GOSSIP_TEXT_OPTIONS; ++i)
  305:         {
  306:             Text_0[i] = pGossip->Options[i].Text_0;
  307:             Text_1[i] = pGossip->Options[i].Text_1;
  308:         }
  309: 
  310:         int loc_idx = session.GetSessionDbLocaleIndex();
  311: 
  312:         sObjectMgr.GetNpcTextLocaleStringsAll(textID, loc_idx, &Text_0, &Text_1);
  313: 
  314:         for (int i = 0; i < MAX_GOSSIP_TEXT_OPTIONS; ++i)
  315:         {
  316:             data << pGossip->Options[i].Probability;
  317: 
  318:             if (Text_0[i].empty())
  319:             {
  320:                 data << Text_1[i];
  321:             }
  322:             else
  323:             {
  324:                 data << Text_0[i];
  325:             }
  326: 
  327:             if (Text_1[i].empty())
  328:             {
  329:                 data << Text_0[i];
  330:             }
  331:             else
  332:             {
  333:                 data << Text_1[i];
  334:             }
  335: 
  336:             data << pGossip->Options[i].Language;
  337: 
  338:             for (int j = 0; j < 3; ++j)
  339:             {
  340:                 data << pGossip->Options[i].Emotes[j]._Delay;
  341:                 data << pGossip->Options[i].Emotes[j]._Emote;
  342:             }
  343:         }
  344:     }
  345: 
  346:     session.SendPacket(&data);
  347: 
  348:     DEBUG_LOG("WORLD: Sent SMSG_NPC_TEXT_UPDATE");
  349: }
