  351: /**
  352:  * @brief Handles an item page text query and sends all linked pages.
  353:  *
  354:  * @param recv_data The incoming page text query packet.
  355:  */
  356: void QueryHandlers::HandlePageTextQuery(WorldSession& session, WorldPacket& recv_data)
  357: {
  358:     DETAIL_LOG("WORLD: Received opcode CMSG_PAGE_TEXT_QUERY");
  359:     recv_data.hexlike();
  360: 
  361:     uint32 pageID;
  362:     recv_data >> pageID;
  363:     recv_data.read_skip<uint64>();                          // guid
  364: 
  365:     while (pageID)
  366:     {
  367:         PageText const* pPage = sObjectMgr.GetPageText(pageID);
  368:         // guess size
  369:         WorldPacket data(SMSG_PAGE_TEXT_QUERY_RESPONSE, 50);
  370:         data << pageID;
  371: 
  372:         if (!pPage)
  373:         {
  374:             data << "Item page missing.";
  375:             data << uint32(0);
  376:             pageID = 0;
  377:         }
  378:         else
  379:         {
  380:             std::string Text = pPage->Text;
  381: 
  382:             int loc_idx = session.GetSessionDbLocaleIndex();
  383:             if (loc_idx >= 0)
  384:             {
  385:                 PageTextLocale const* pl = sObjectMgr.GetPageTextLocale(pageID);
  386:                 if (pl)
  387:                 {
  388:                     if (pl->Text.size() > size_t(loc_idx) && !pl->Text[loc_idx].empty())
  389:                     {
  390:                         Text = pl->Text[loc_idx];
  391:                     }
  392:                 }
  393:             }
  394: 
  395:             data << Text;
  396:             data << uint32(pPage->Next_Page);
  397:             pageID = pPage->Next_Page;
  398:         }
  399:         session.SendPacket(&data);
  400: 
  401:         DEBUG_LOG("WORLD: Sent SMSG_PAGE_TEXT_QUERY_RESPONSE");
  402:     }
  403: }
