  420: void QueryHandlers::HandleQueryQuestsCompleted(WorldSession& session, WorldPacket& /*recv_data */)
  421: {
  422:     uint32 count = 0;
  423: 
  424:     WorldPacket data(SMSG_ALL_QUESTS_COMPLETED, 4 + 4 * count);
  425:     data << uint32(count);
  426: 
  427:     for (QuestStatusMap::const_iterator itr = session.GetPlayer()->GetQuestStatusMgr().Map().begin(); itr != session.GetPlayer()->GetQuestStatusMgr().Map().end(); ++itr)
  428:     {
  429:         if (itr->second.m_rewarded)
  430:         {
  431:             data << uint32(itr->first);
  432:             ++count;
  433:         }
  434:     }
  435:     data.put<uint32>(0, count);
  436:     session.SendPacket(&data);
  437: }
