  113:     set(CANDIDATE "${FROM_DIR}/${INCLUDE}")
  114:     if(EXISTS "${CANDIDATE}" AND NOT IS_DIRECTORY "${CANDIDATE}")
  115:         get_filename_component(CANDIDATE "${CANDIDATE}" REALPATH)
  116:         set(${OUT_VAR} "${CANDIDATE}" PARENT_SCOPE)
  117:         return()
  118:     endif()
  119:     get_filename_component(BASENAME "${INCLUDE}" NAME)
  120:     foreach(DIR IN LISTS INCLUDE_DIRS)
  121:         foreach(NAME IN ITEMS "${INCLUDE}" "${BASENAME}")
  122:             set(CANDIDATE "${DIR}/${NAME}")
  123:             if(EXISTS "${CANDIDATE}" AND NOT IS_DIRECTORY "${CANDIDATE}")
  124:                 get_filename_component(CANDIDATE "${CANDIDATE}" REALPATH)
  125:                 set(${OUT_VAR} "${CANDIDATE}" PARENT_SCOPE)
