  133: function(walk_includes START OUT_VAR)
  134:     set(QUEUE "${START}")
  135:     set(SEEN "")
  136:     while(QUEUE)
  137:         list(POP_FRONT QUEUE CURRENT)
  138:         file(STRINGS "${CURRENT}" LINES REGEX "^[ \t]*#[ \t]*include")
  139:         get_filename_component(CURRENT_DIR "${CURRENT}" DIRECTORY)
  140:         foreach(LINE IN LISTS LINES)
  141:             string(REGEX MATCH "[\"<]([^\">]+)[\">]" _ "${LINE}")
  142:             set(INCLUDE "${CMAKE_MATCH_1}")
  143:             if(NOT INCLUDE)
  144:                 continue()
  145:             endif()
  146:             resolve_include("${INCLUDE}" "${CURRENT_DIR}" RESOLVED)
  147:             if(RESOLVED AND NOT RESOLVED IN_LIST SEEN)
  148:                 list(APPEND SEEN "${RESOLVED}")
  149:                 list(APPEND QUEUE "${RESOLVED}")
  150:             endif()
  151:         endforeach()
  152:     endwhile()
  153:     set(${OUT_VAR} "${SEEN}" PARENT_SCOPE)
  154: endfunction()
